def load() -> pd.DataFrame:
    with open('data/wildfire/input/nifc_wildfires.csv', 'r') as f:
        lines = [f.readline() for _ in range(5)]
    return pd.DataFrame({'raw': lines})

def process(noaa_data) -> pd.DataFrame:
    df = noaa_data.copy()
    df['Year'] = df['Date'].astype(str).str[:4].astype(int)
    return df.groupby('Year', as_index=False).agg(
        noaa_fires=('Number of Fires', 'sum'),
        noaa_acres=('Acres Burned', 'sum')
    )
